#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static char *read_all(void) {
    size_t cap = 4096, len = 0;
    char *s = (char *)malloc(cap);
    if (!s) return NULL;
    int ch;
    while ((ch = getchar()) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = (char *)realloc(s, cap);
            if (!tmp) { free(s); return NULL; }
            s = tmp;
        }
        s[len++] = (char)ch;
    }
    s[len] = '\0';
    return s;
}

static void skip_ws(const char *s, size_t *p) {
    while (s[*p] == ' ' || s[*p] == '\t' || s[*p] == '\n' || s[*p] == '\r' || s[*p] == ',') (*p)++;
}

static int *parse_array(const char *s, size_t *p, int *n) {
    while (s[*p] && s[*p] != '[') (*p)++;
    if (!s[*p]) return NULL;
    (*p)++;
    int cap = 16, len = 0;
    int *a = (int *)malloc((size_t)cap * sizeof(int));
    if (!a) return NULL;

    while (s[*p] && s[*p] != ']') {
        skip_ws(s, p);
        if (s[*p] == ']') break;
        if (!isdigit((unsigned char)s[*p])) { free(a); return NULL; }
        int v = 0;
        while (isdigit((unsigned char)s[*p])) {
            v = v * 10 + (s[*p] - '0');
            (*p)++;
        }
        if (len == cap) {
            cap *= 2;
            int *tmp = (int *)realloc(a, (size_t)cap * sizeof(int));
            if (!tmp) { free(a); return NULL; }
            a = tmp;
        }
        a[len++] = v;
        skip_ws(s, p);
    }
    if (s[*p] == ']') (*p)++;
    *n = len;
    return a;
}

int canCompleteCircuit(int *gas, int gasSize, int *cost, int costSize) {
    (void)costSize;
    long long total = 0, tank = 0;
    int start = 0;
    for (int i = 0; i < gasSize; ++i) {
        long long d = (long long)gas[i] - cost[i];
        total += d;
        tank += d;
        if (tank < 0) { tank = 0; start = i + 1; }
    }
    return total >= 0 ? start : -1;
}

